const sample = "fn f(x: i32) -> i32 { x + 1 }\n"

func newInstance(t *testing.T, limit int64) (engine.Module, *[]byte) {
	t.Helper()
	h := &engine.Host{}
	m := grammar.New(h)
	mem := m.Xmemory().Slice()
	t.Cleanup(func() { engine.Release(mem) })
	if err := engine.SetLimit(mem, limit); err != nil {
		t.Fatal(err)
	}
	if err := engine.Call(m.X_initialize); err != nil {
		t.Fatal(err)
	}
	if v := m.Xtsg_abi_version(); v != engine.ABIVersion {
		t.Fatalf("tsg_abi_version = %d, want %d", v, engine.ABIVersion)
	}
	if r := m.Xtsg_init(); r != 0 {
		t.Fatalf("tsg_init = %d", r)
	}
	// the export chunk buffer exists right after tsg_init, header already written
	buf := int(m.Xtsg_export_buf())
	if buf == 0 || string((*mem)[buf:buf+4]) != engine.ExportMagic ||
		binary.LittleEndian.Uint16((*mem)[buf+4:]) != engine.ExportFormat || u32(mem, buf+8) == 0 {
		t.Fatalf("export buffer after tsg_init: ptr %d", buf)
	}
	return m, mem
}

func put(t *testing.T, m engine.Module, mem *[]byte, b []byte) int32 {
	t.Helper()
	p := m.Xmalloc(int32(len(b)) + 1)
	if p == 0 {
		t.Fatalf("malloc(%d) failed", len(b))
	}
	copy((*mem)[p:], b)
	return p
}

func u32(mem *[]byte, off int) uint32 { return binary.LittleEndian.Uint32((*mem)[off:]) }

// inputs is the embedded sample plus, when TSG_CORPUS names a directory of source files, up to five of them.
func inputs(t *testing.T) map[string][]byte {
	in := map[string][]byte{"sample": []byte(sample)}
	dir := os.Getenv("TSG_CORPUS")
	if dir == "" {
		t.Log("TSG_CORPUS is not set: corpus files skipped, embedded sample only")
		return in
	}
	names, _ := filepath.Glob(filepath.Join(dir, "*"))
	sort.Strings(names)
	for _, n := range names {
		if b, err := os.ReadFile(n); err == nil && len(b) > 0 && len(b) <= 1<<20 && len(in) < 6 {
			in[filepath.Base(n)] = b
		}
	}
	return in
}

// parseAndExport parses src, checks the root extent and the complete export, and returns the tree.
func parseAndExport(t *testing.T, m engine.Module, mem *[]byte, src []byte) int32 {
	t.Helper()
	p := put(t, m, mem, src)
	defer m.Xfree(p)
	tree := m.Xtsg_parse(p, int32(len(src)), 0)
	if tree == 0 {
		t.Fatal("tsg_parse returned NULL")
	}
	if end := m.Xtsg_root_end(tree); int(end) != len(src) {
		t.Fatalf("root end %d, input %d", end, len(src))
	}
	dc := m.Xtsg_descendant_count(tree)
	rootErr := m.Xtsg_root_has_error(tree)
	if n := m.Xtsg_export_begin(tree); n != dc || n == 0 {
		t.Fatalf("export_begin = %d, descendant count %d", n, dc)
	}
	buf := int(m.Xtsg_export_buf())
	if buf == 0 || string((*mem)[buf:buf+4]) != engine.ExportMagic ||
		binary.LittleEndian.Uint16((*mem)[buf+4:]) != engine.ExportFormat {
		t.Fatalf("export header %q", (*mem)[buf:buf+16])
	}
	kc := int(u32(mem, buf+8))
	if kc == 0 || kc%4 != 0 {
		t.Fatalf("chunk capacity %d", kc)
	}
	total := 0
	for {
		k := int(m.Xtsg_export_next())
		if k == 0 {
			break
		}
		if k > kc {
			t.Fatalf("chunk of %d nodes, capacity %d", k, kc)
		}
		if total == 0 { // first node is the root: parent -1, starts a named node, ends at the input end
			c := buf + 16
			if has := (*mem)[c+4*kc]&16 != 0; has != (rootErr != 0) {
				t.Fatalf("tsg_root_has_error = %d, root has_error flag = %v", rootErr, has)
			}
			if int32(u32(mem, c+29*kc)) != -1 || (*mem)[c+4*kc]&1 == 0 || int(u32(mem, c+9*kc)) != len(src) {
				t.Fatal("first exported node is not the root")
			}
			if sym := binary.LittleEndian.Uint16((*mem)[c:]); int(sym) >= len(grammar.Meta.Symbols) || grammar.Meta.Symbols[sym] == "" {
				t.Fatalf("root symbol %d has no name in the static meta", sym)
			}
		}
		total += k
	}
	if int32(total) != dc || m.Xtsg_export_err() != 0 {
		t.Fatalf("exported %d nodes, want %d, err=%d", total, dc, m.Xtsg_export_err())
	}
	m.Xtsg_export_end()
	m.Xtsg_export_end() // idempotent
	return tree
}

func TestSmoke(t *testing.T) {
	m, mem := newInstance(t, 256<<20)
	for name, src := range inputs(t) {
		t.Run(name, func(t *testing.T) {
			tree := parseAndExport(t, m, mem, src)
			m.Xtsg_tree_delete(tree)
		})
	}
	if engine.Refused(mem) {
		t.Fatal("a grow was refused during normal parsing")
	}
}

// tsg_root_has_error agrees with the exported flag for a clean and for a broken input.
func TestRootHasError(t *testing.T) {
	m, mem := newInstance(t, 256<<20)
	for _, c := range []struct {
		name string
		src  string
		want int32
	}{{"clean", sample, 0}, {"broken", sample + "}}}]]]))) <<<>>> ", 1}} {
		p := put(t, m, mem, []byte(c.src))
		tree := m.Xtsg_parse(p, int32(len(c.src)), 0)
		if tree == 0 {
			t.Fatalf("%s: parse returned NULL", c.name)
		}
		if got := m.Xtsg_root_has_error(tree); got != c.want {
			t.Fatalf("%s: tsg_root_has_error = %d, want %d", c.name, got, c.want)
		}
		m.Xtsg_tree_delete(tree)
		m.Xfree(p)
	}
}

// tsg_changed_ranges never returns NULL: two identical trees give a count = 0 block.
func TestChangedRangesEmptyIsNotNull(t *testing.T) {
	m, mem := newInstance(t, 256<<20)
	src := []byte(sample)
	p := put(t, m, mem, src)
	defer m.Xfree(p)
	a := m.Xtsg_parse(p, int32(len(src)), 0)
	b := m.Xtsg_parse(p, int32(len(src)), a)
	blk := int(m.Xtsg_changed_ranges(a, b))
	if blk == 0 || u32(mem, blk) != 0 {
		t.Fatalf("empty changed-ranges block: ptr %d", blk)
	}
	m.Xfree(int32(blk))
	m.Xtsg_tree_delete(a)
	m.Xtsg_tree_delete(b)
}

func TestChangedRanges(t *testing.T) {
	m, mem := newInstance(t, 256<<20)
	old := parseAndExport(t, m, mem, []byte(sample))
	m.Xtsg_tree_edit(old, 0, 0, 1, 0, 0, 0, 0, 1, 0) // insert "\n" at the start
	src := []byte("\n" + sample)
	p := put(t, m, mem, src)
	defer m.Xfree(p)
	neu := m.Xtsg_parse(p, int32(len(src)), old)
	if neu == 0 {
		t.Fatal("incremental parse returned NULL")
	}
	blk := int(m.Xtsg_changed_ranges(old, neu))
	if blk == 0 {
		t.Fatal("tsg_changed_ranges returned NULL")
	}
	n := int(u32(mem, blk))
	if blk+4+24*n > len(*mem) {
		t.Fatalf("changed-ranges block of %d entries overruns memory", n)
	}
	for i := 0; i < n; i++ {
		o := blk + 4 + 24*i
		if u32(mem, o) > u32(mem, o+4) {
			t.Fatalf("range %d: start %d after end %d", i, u32(mem, o), u32(mem, o+4))
		}
	}
	m.Xfree(int32(blk))
	m.Xtsg_tree_delete(old)
	m.Xtsg_tree_delete(neu)
}

// A refused memory.grow makes the C runtime abort; the generated code panics and engine.Call reports a *Trap.
func TestGrowRefusalTraps(t *testing.T) {
	m, mem := newInstance(t, engine.MinLimit)
	big := bytes.Repeat([]byte(sample), (12<<20)/len(sample))
	p := put(t, m, mem, big)
	err := engine.Call(func() { m.Xtsg_parse(p, int32(len(big)), 0) })
	var trap *engine.Trap
	if !errors.As(err, &trap) {
		t.Fatalf("parse under a %d MiB limit returned %v, want *engine.Trap", engine.MinLimit>>20, err)
	}
	if !engine.Refused(mem) {
		t.Fatal("trap without a refused grow")
	}
	engine.Release(mem)
	if *mem != nil || engine.Committed(mem) != 0 {
		t.Fatal("memory not released after the trap")
	}
}

func TestIdentityMatchesProvenance(t *testing.T) {
	b, err := os.ReadFile("provenance.json")
	if err != nil {
		t.Fatal(err)
	}
	var pj struct {
		ABI      uint32
		Name     string
		Module   string
		Identity engine.Identity
		Outputs  map[string]string
	}
	if err := json.Unmarshal(b, &pj); err != nil {
		t.Fatal(err)
	}
	if pj.ABI != grammar.ABI || pj.Name != grammar.Name {
		t.Fatalf("provenance abi/name %d/%q, compiled %d/%q", pj.ABI, pj.Name, grammar.ABI, grammar.Name)
	}
	if !reflect.DeepEqual(pj.Identity, grammar.Identity) {
		t.Fatalf("provenance.json identity differs from the compiled one:\n%+v\n%+v", pj.Identity, grammar.Identity)
	}
	// every generated source file of the module is bound by provenance; engine_gen.dat exists only for the embed recipes
	for _, name := range []string{"engine_gen.go", "engine_gen.dat"} {
		gen, err := os.ReadFile(name)
		if errors.Is(err, os.ErrNotExist) && name == "engine_gen.dat" {
			if _, ok := pj.Outputs[name]; ok {
				t.Fatalf("provenance lists %s but the file is absent", name)
			}
			continue
		} else if err != nil {
			t.Fatal(err)
		}
		sum := sha256.Sum256(gen)
		if got := hex.EncodeToString(sum[:]); got != pj.Outputs[name] {
			t.Fatalf("%s sha256 %s, provenance %s", name, got, pj.Outputs[name])
		}
	}
	// the license texts of the linked wasi-libc are bound by provenance too
	notices := 0
	for name, want := range pj.Outputs {
		if !strings.HasPrefix(name, "LICENSES/") {
			continue
		}
		b, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		if sum := sha256.Sum256(b); hex.EncodeToString(sum[:]) != want {
			t.Fatalf("%s differs from provenance", name)
		}
		notices++
	}
	if notices == 0 {
		t.Fatal("provenance lists no license notices")
	}
	if grammar.ABI != engine.ABIVersion {
		t.Fatalf("grammar ABI %d, engine ABI %d", grammar.ABI, engine.ABIVersion)
	}
}
